    auto snap = leader.snapshot();
    auto owned = collect_changes(leader.changes_since(snap, 0));
    auto views = owned.views();

    std::size_t split = views.size() / 2;
    {
      bool in_batch = false;
      for (std::size_t i = 0; i < split; ++i) {
        if (views[i].entry_type == bytecask::EntryType::BulkBegin) in_batch = true;
        else if (views[i].entry_type == bytecask::EntryType::BulkEnd) in_batch = false;
      }
      if (in_batch) {
        while (split < views.size() &&
               views[split].entry_type != bytecask::EntryType::BulkEnd) ++split;
        if (split < views.size()) ++split;
      }
    }
    auto chunk1 = std::span<const bytecask::DataEntryView>{views.data(), split};

    // First pass: ingest first half, close follower.
    {
      auto follower = bytecask::DB::open(follower_dir,
          {.initial_mode = bytecask::Mode::Follower});
      if (!chunk1.empty()) follower.ingest(chunk1);
    }

